<?php
/**
 * BET Sitemap Explorer
 * Reads data/sitemap_manifest.json (written by includes/sitemap-builder.php) and serves it
 * through server-side search/filter/sort/pagination. The manifest itself is never re-parsed
 * from XML here, and never regenerated by this file — that's tools/build_sitemap.php's job,
 * fired automatically by includes/sitemap-autobuild.php on ordinary site traffic.
 */

require_once dirname(__DIR__) . '/includes/config.php';

// ── Domain auto-detection (kept from the previous version) ──────────────────────────────────
$protocol = isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] === 'on' ? 'https' : 'http';
$host = $_SERVER['HTTP_HOST'];
$base_dir = dirname($_SERVER['SCRIPT_NAME']);
if ($base_dir === '\\' || $base_dir === '/') $base_dir = '';
$current_base_url = rtrim($protocol . '://' . $host . $base_dir, '/');

// ── Load manifest (server-side only; never shipped to the browser in full) ──────────────────
$manifest_file = dirname(__DIR__) . '/data/sitemap_manifest.json';
$manifest = file_exists($manifest_file) ? json_decode(file_get_contents($manifest_file), true) : null;
$entries = is_array($manifest) ? ($manifest['entries'] ?? []) : [];
$generated_at = is_array($manifest) ? ($manifest['generated_at'] ?? null) : null;

// Optional HTTP-status cache written by tools/validate_sitemap.php (Phase 8/9 verification).
// Its absence is not an error — rows simply show "Unchecked" until a validation pass has run.
$status_file = dirname(__DIR__) . '/data/sitemap_status.json';
$status_map = [];
if (file_exists($status_file)) {
    $decoded = json_decode(file_get_contents($status_file), true);
    if (is_array($decoded) && isset($decoded['urls'])) {
        $status_map = $decoded['urls'];
    }
}

// ── Category taxonomy: 1:1 with the manifest's own 'category' field, no substring guessing ──
// This is what guarantees "no mixing, no duplicate entries" between tabs — every entry belongs
// to exactly one manifest category, and every tab maps to exactly one (or a small fixed) set
// of those categories.
$TAB_MAP = [
    'ALL'               => null, // no filter
    'PRODUCTS'          => ['static', 'product', 'product_category'],
    'LOCATIONS'         => ['location'],
    'LOCATION_PRODUCT'  => ['location_product'],
    'GALLERIES'         => ['location_product_gallery'],
    'INDUSTRIES'        => ['industry'],
    'IMAGES'            => ['image'],
    'DOWNLOADS'         => ['download'],
    'DOCUMENTATION'     => ['documentation'],
];

$CATEGORY_LABELS = [
    'static'                   => 'Static Page',
    'product'                  => 'Product',
    'product_category'         => 'Product Category',
    'location'                 => 'Location',
    'location_product'         => 'Location + Product',
    'location_product_gallery' => 'Location + Product Gallery',
    'industry'                 => 'Industry',
    'image'                    => 'Image',
    'download'                 => 'Download',
    'documentation'            => 'Documentation',
];

function normalize_search_text(string $s): string {
    // A trailing slash carries no search intent of its own — "vacuum-glove-box/" and
    // "vacuum-glove-box" must match exactly the same rows. Without this, entries whose
    // matching text isn't immediately followed by a literal "/" (e.g. a label like
    // "Acrylic Vacuum Glove Box", or a slug continuation like "...-buying-guide") would be
    // silently excluded by a query that happens to end in "/".
    return rtrim(strtolower(str_replace(['-', '_'], ' ', $s)), '/');
}

/**
 * Relativizes a pasted URL down to the manifest's own storage form before it ever reaches
 * normalize_search_text(). Handles:
 *   - absolute URLs on any host ("http://localhost/BET/products/x/", "https://prod.com/products/x/")
 *   - the site's own base path ("/BET" locally, "" in a root-deployed production install)
 * so searching works identically whether the user types a bare slug or pastes a full URL
 * copied from the address bar, from the XML sitemap, or from the Explorer's own "Open" link.
 */
function strip_url_prefix(string $q, string $base_url): string {
    $q = trim($q);
    if ($q === '') return $q;

    // Strip scheme + host (works for localhost, 127.0.0.1, or any production domain — the
    // manifest never stores a domain, so any domain prefix on the query is noise to remove).
    $q = preg_replace('#^https?://[^/]+#i', '', $q);

    // Strip this site's own base path (e.g. "/BET") if the remainder still starts with it,
    // so a full pasted URL collapses to the same relative form the manifest stores.
    $base_path = rtrim((string) parse_url($base_url, PHP_URL_PATH), '/');
    if ($base_path !== '' && stripos($q, $base_path) === 0) {
        $q = substr($q, strlen($base_path));
    }

    return $q;
}

/** Rewrites a manifest-relative URL (e.g. "/products/vacuum-glove-box/") to a full domain URL. */
function full_url(string $rel, string $base): string {
    if ($rel === '/') return $base . '/';
    $encoded = implode('/', array_map('rawurlencode', explode('/', trim($rel, '/'))));
    return $base . '/' . $encoded;
}

/**
 * Applies search + category + status + priority filters to the full entry list.
 * Shared by the AJAX endpoint and the export endpoint so both see identical result sets.
 */
function filter_entries(array $entries, ?array $categories, string $search, array $status_map): array {
    $q = trim($search) !== '' ? normalize_search_text($search) : '';

    return array_values(array_filter($entries, function ($e) use ($categories, $q) {
        if ($categories !== null && !in_array($e['category'], $categories, true)) {
            return false;
        }

        if ($q !== '') {
            $haystack = normalize_search_text(
                ($e['url'] ?? '') . ' ' .
                ($e['label'] ?? '') . ' ' .
                ($e['file'] ?? '') . ' ' .
                ($e['parent'] ?? '') . ' ' .
                ($e['category'] ?? '')
            );
            if (strpos($haystack, $q) === false) {
                return false;
            }
        }

        return true;
    }));
}

function sort_entries(array $entries, string $sort, string $dir, array $status_map): array {
    $mult = $dir === 'desc' ? -1 : 1;
    usort($entries, function ($a, $b) use ($sort, $mult, $status_map) {
        switch ($sort) {
            case 'category':
                return $mult * strcmp($a['category'], $b['category']);
            case 'lastmod':
                return $mult * strcmp($a['lastmod'] ?? '', $b['lastmod'] ?? '');
            case 'priority':
                return $mult * ((float)($a['priority'] ?? 0) <=> (float)($b['priority'] ?? 0));
            case 'status':
                $ca = $status_map[$a['url']]['code'] ?? -1;
                $cb = $status_map[$b['url']]['code'] ?? -1;
                return $mult * ($ca <=> $cb);
            case 'url':
            default:
                return $mult * strcmp($a['url'], $b['url']);
        }
    });
    return $entries;
}

function status_bucket_for(string $url, array $status_map): array {
    if (!isset($status_map[$url])) {
        return ['bucket' => 'unchecked', 'label' => 'Unchecked', 'code' => null];
    }
    $code = $status_map[$url]['code'] ?? null;
    $method = $status_map[$url]['method'] ?? 'live';
    if ($code === null) return ['bucket' => 'unchecked', 'label' => 'Unchecked', 'code' => null];
    if ($code >= 200 && $code < 300) {
        $label = $method === 'structural' ? 'Valid (structural)' : 'Live 200';
        return ['bucket' => 'live', 'label' => $label, 'code' => $code];
    }
    if ($code >= 300 && $code < 400) return ['bucket' => 'redirect', 'label' => "Redirect {$code}", 'code' => $code];
    return ['bucket' => 'broken', 'label' => "Broken {$code}", 'code' => $code];
}

// ── Global (unfiltered) stats — computed once from the full manifest, cheap (single pass) ───
function compute_global_stats(array $entries): array {
    $stats = ['total' => count($entries)];
    foreach (['static', 'product', 'product_category', 'location', 'location_product', 'location_product_gallery', 'industry', 'image', 'download', 'documentation'] as $c) {
        $stats[$c] = 0;
    }
    foreach ($entries as $e) {
        if (isset($stats[$e['category']])) $stats[$e['category']]++;
    }
    $stats['products_tab'] = $stats['static'] + $stats['product'] + $stats['product_category'];
    return $stats;
}

$global_stats = compute_global_stats($entries);

// ══════════════════════════════════════════════════════════════════════════════════════════
// AJAX / EXPORT ENDPOINTS — everything below returns early with JSON or a file download.
// The HTML shell (further down) is only rendered for a plain page load.
// ══════════════════════════════════════════════════════════════════════════════════════════

$action = $_GET['action'] ?? '';

if ($action === 'query') {
    $tab      = strtoupper($_GET['tab'] ?? 'ALL');
    $search   = strip_url_prefix((string)($_GET['q'] ?? ''), $current_base_url);
    $sort     = $_GET['sort'] ?? 'url';
    $dir      = ($_GET['dir'] ?? 'asc') === 'desc' ? 'desc' : 'asc';
    $page     = max(1, (int)($_GET['page'] ?? 1));
    $per_page = 100;

    if (!array_key_exists($tab, $TAB_MAP)) $tab = 'ALL';

    $categories = $TAB_MAP[$tab];
    $filtered = filter_entries($entries, $categories, $search, $status_map);
    $filtered = sort_entries($filtered, $sort, $dir, $status_map);
    $filtered_count = count($filtered);

    // action === 'query' → paginate and return JSON
    $total_pages = max(1, (int)ceil($filtered_count / $per_page));
    if ($page > $total_pages) $page = $total_pages;
    $offset = ($page - 1) * $per_page;
    $page_slice = array_slice($filtered, $offset, $per_page);

    $rows = array_map(function ($e) use ($current_base_url, $CATEGORY_LABELS, $status_map) {
        $s = status_bucket_for($e['url'], $status_map);
        $row = [
            'url'          => full_url($e['url'], $current_base_url),
            'rel'          => $e['url'],
            'category'     => $e['category'],
            'category_label' => $CATEGORY_LABELS[$e['category']] ?? $e['category'],
            'label'        => $e['label'] ?? '',
            'lastmod'      => $e['lastmod'] ?? '',
            'priority'     => $e['priority'] ?? '',
            'changefreq'   => $e['changefreq'] ?? '',
            'status_bucket'=> $s['bucket'],
            'status_label' => $s['label'],
        ];
        if ($e['category'] === 'image') {
            $row['caption'] = $e['caption'] ?? '';
        }
        if ($e['category'] === 'download') {
            $row['filetype'] = $e['filetype'] ?? '';
            $row['size'] = $e['size'] ?? null;
        }
        return $row;
    }, $page_slice);

    header('Content-Type: application/json');
    echo json_encode([
        'rows'          => $rows,
        'total'         => $filtered_count,
        'page'          => $page,
        'per_page'      => $per_page,
        'total_pages'   => $total_pages,
        'global_stats'  => $global_stats,
    ], JSON_UNESCAPED_SLASHES);
    exit;
}

// ══════════════════════════════════════════════════════════════════════════════════════════
// PLAIN PAGE LOAD — render the HTML shell. Rows are fetched by JS via ?action=query.
// ══════════════════════════════════════════════════════════════════════════════════════════
?>
