                    <th class="sortable" data-sort="priority">Priority <span class="sort-icon"><i class="fas fa-sort"></i></span></th>
                    <th class="sortable" data-sort="status">Status <span class="sort-icon"><i class="fas fa-sort"></i></span></th>
