<div class="toast" id="copy-toast">URL Copied to clipboard!</div>

<div class="modal-backdrop" id="preview-modal">
    <div class="modal-box">
        <button class="modal-close" id="modal-close-btn">&times;</button>
        <div id="modal-content"></div>
    </div>
</div>

<script>
const ENDPOINT = window.location.pathname; // this same file, with ?action=query / ?action=export
const categoryLabels = {
    'static': 'Static Page', 'product': 'Product', 'product_category': 'Product Category',
    'location': 'Location', 'location_product': 'Location + Product', 'location_product_gallery': 'Location + Product Gallery',
    'industry': 'Industry', 'image': 'Image', 'download': 'Download', 'documentation': 'Documentation'
};

let state = {
    tab: 'ALL',
    q: '',
    sort: 'url',
    dir: 'asc',
    page: 1
};

let debounceTimer = null;
let requestSeq = 0; // guards against out-of-order responses when requests overlap

function buildQuery(extra) {
    const params = new URLSearchParams(Object.assign({
        action: 'query',
        tab: state.tab,
        q: state.q,
        sort: state.sort,
        dir: state.dir,
        page: state.page
    }, extra || {}));
    return ENDPOINT + '?' + params.toString();
}

async function fetchAndRender() {
    const mySeq = ++requestSeq;
    document.getElementById('loading-overlay').style.display = 'flex';
    try {
        const res = await fetch(buildQuery());
        const data = await res.json();
        if (mySeq !== requestSeq) return; // a newer request has already superseded this one
        renderRows(data);
        renderPagination(data);
    } catch (err) {
        console.error('Sitemap explorer query failed', err);
    } finally {
        if (mySeq === requestSeq) document.getElementById('loading-overlay').style.display = 'none';
    }
}

function escapeHtml(s) {
    const d = document.createElement('div');
    d.innerText = s;
    return d.innerHTML;
}

function renderRows(data) {
    const tbody = document.getElementById('table-body');
    const emptyState = document.getElementById('empty-state');

    if (data.rows.length === 0) {
        tbody.innerHTML = '';
        emptyState.style.display = 'block';
        return;
    }
    emptyState.style.display = 'none';

    tbody.innerHTML = data.rows.map((item, idx) => {
        const catClass = item.category;
        let leading = '';
        if (item.category === 'image') {
            leading = `<img class="url-thumb" src="${item.url}" loading="lazy" alt="">`;
        } else if (item.category === 'download') {
            const icon = { pdf: 'fa-file-pdf', doc: 'fa-file-word', docx: 'fa-file-word',
                xls: 'fa-file-excel', xlsx: 'fa-file-excel', ppt: 'fa-file-powerpoint',
                pptx: 'fa-file-powerpoint', zip: 'fa-file-zipper', rar: 'fa-file-zipper',
                software: 'fa-download' }[item.filetype] || 'fa-file';
            leading = `<span class="file-icon"><i class="fas ${icon}"></i></span>`;
        }
        return `
            <tr>
                <td class="url-cell">${leading}<a href="${item.url}" class="url-link" target="_blank" rel="noopener" title="${escapeHtml(item.url)}">${escapeHtml(item.rel)}</a></td>
                <td><span class="badge badge-${catClass}">${item.category_label}</span></td>
                <td>${item.lastmod}</td>
                <td>${item.priority}</td>
                <td><span class="badge badge-${item.status_bucket}">${item.status_label}</span></td>
                <td>
                    <button class="action-btn" onclick="window.open('${item.url}', '_blank')" title="Open Link"><i class="fas fa-external-link-alt"></i></button>
                    <button class="action-btn" onclick="copyUrl('${item.url}')" title="Copy Link"><i class="far fa-copy"></i></button>
                    <button class="action-btn" onclick='openPreview(${JSON.stringify(item)})' title="Preview"><i class="fas fa-eye"></i></button>
                </td>
            </tr>
        `;
    }).join('');
}

function renderPagination(data) {
    const info = document.getElementById('pagination-info');
    const controls = document.getElementById('pagination-controls');

    if (data.total === 0) {
        info.innerText = 'Showing 0 URLs';
        controls.innerHTML = '';
        return;
    }

    const start = (data.page - 1) * data.per_page + 1;
    const end = Math.min(data.page * data.per_page, data.total);
    info.innerText = `Showing ${start.toLocaleString()} to ${end.toLocaleString()} of ${data.total.toLocaleString()} URLs`;

    let html = `<button class="page-btn" ${data.page === 1 ? 'disabled' : ''} onclick="goToPage(${data.page - 1})">Previous</button>`;
    let startPage = Math.max(1, data.page - 2);
    let endPage = Math.min(data.total_pages, startPage + 4);
    if (endPage - startPage < 4) startPage = Math.max(1, endPage - 4);
    for (let i = startPage; i <= endPage; i++) {
        html += `<button class="page-btn ${i === data.page ? 'active' : ''}" onclick="goToPage(${i})">${i}</button>`;
    }
    html += `<button class="page-btn" ${data.page === data.total_pages ? 'disabled' : ''} onclick="goToPage(${data.page + 1})">Next</button>`;
    controls.innerHTML = html;
}

function goToPage(page) {
    state.page = page;
    fetchAndRender();
    window.scrollTo({ top: 350, behavior: 'smooth' });
}

function copyUrl(url) {
    navigator.clipboard.writeText(url).then(() => {
        const toast = document.getElementById('copy-toast');
        toast.style.opacity = '1';
        setTimeout(() => toast.style.opacity = '0', 2000);
    });
}

function openPreview(item) {
    const modal = document.getElementById('preview-modal');
    const content = document.getElementById('modal-content');
    let inner = `<h3>${escapeHtml(item.rel)}</h3>`;

    if (item.category === 'image') {
        inner += `<img src="${item.url}" alt="">`;
        if (item.caption) inner += `<p style="color:var(--text-muted);margin-bottom:1rem;">Folder: ${escapeHtml(item.caption)}</p>`;
    } else if (item.category === 'download') {
        const sizeKb = item.size ? Math.round(item.size / 1024) : null;
        inner += `<p style="margin-bottom:1rem;">Type: <strong>${(item.filetype || '').toUpperCase()}</strong>${sizeKb ? ' &middot; Size: <strong>' + sizeKb.toLocaleString() + ' KB</strong>' : ''}</p>`;
    }

    const xml = `<url>\n  <loc>${item.url}</loc>\n  <lastmod>${item.lastmod}</lastmod>\n  <changefreq>${item.changefreq || ''}</changefreq>\n  <priority>${item.priority}</priority>\n</url>`;
    inner += `<p style="font-weight:600;margin-bottom:0.5rem;">Sitemap XML entry</p><pre>${escapeHtml(xml)}</pre>`;

    content.innerHTML = inner;
    modal.classList.add('open');
}

document.getElementById('modal-close-btn').addEventListener('click', () => {
    document.getElementById('preview-modal').classList.remove('open');
});
document.getElementById('preview-modal').addEventListener('click', (e) => {
    if (e.target.id === 'preview-modal') e.target.classList.remove('open');
});

function attachEvents() {
    document.getElementById('search-input').addEventListener('input', (e) => {
        clearTimeout(debounceTimer);
        const val = e.target.value;
        debounceTimer = setTimeout(() => {
            state.q = val;
            state.page = 1;
            fetchAndRender();
        }, 250); // debounce so we don't fire a request on every keystroke
    });

    document.querySelectorAll('.filter-btn[data-tab]').forEach(btn => {
        btn.addEventListener('click', (e) => {
            document.querySelectorAll('.filter-btn[data-tab]').forEach(b => b.classList.remove('active'));
            e.currentTarget.classList.add('active');
            state.tab = e.currentTarget.getAttribute('data-tab');
            state.page = 1;
            fetchAndRender();
        });
    });

    document.querySelectorAll('th.sortable').forEach(th => {
        th.addEventListener('click', () => {
            const col = th.getAttribute('data-sort');
            if (state.sort === col) {
                state.dir = state.dir === 'asc' ? 'desc' : 'asc';
            } else {
                state.sort = col;
                state.dir = 'asc';
            }
            document.querySelectorAll('th.sortable .sort-icon i').forEach(i => i.className = 'fas fa-sort');
            th.querySelector('.sort-icon i').className = state.dir === 'asc' ? 'fas fa-sort-up' : 'fas fa-sort-down';
            fetchAndRender();
        });
    });
}

attachEvents();
fetchAndRender();
</script>
</body>
</html>
